    """Extend the zero square's row and column lines, preserving 2s."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    zeros = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == 0}
    # The marker is the contiguous 2x2 zero square.
    anchor = next(
        (r, c)
        for r in range(h - 1)
        for c in range(w - 1)
        if all((rr, cc) in zeros for rr, cc in ((r, c), (r + 1, c), (r, c + 1), (r + 1, c + 1)))
    )
    r0, c0 = anchor
    for r in (r0, r0 + 1):
        for c in range(w):
            if grid[r][c] != 2:
                out[r][c] = 0
    for c in (c0, c0 + 1):
        for r in range(h):
            if grid[r][c] != 2:
                out[r][c] = 0
    return out
